"use client";
import {Fragment,useEffect,useRef,useState} from 'react';
import {useRouter} from 'next/navigation';
import Link from 'next/link';
import type {JobDetail} from '@/types/job';
import type {JobWorkflow,JobOption,JobSiteData,JobOrderOption} from '@/lib/jobSiteData';
import {AccidentReportModal} from '@/components/accident-report-search/AccidentReportModal';
import styles from './JobProfileScreen.module.css';
const legalTabs=['Statement of Account','Notice of Identification','Notice of Contract','Satisfaction of Claim of Lien','Satisfaction of Notice of Contract','Stop Payment Notice','Money Owed','Bond Claim'];
const tabs=['Site Data','Job Order','Contacts','Certified Payroll','Directions','Accident Reports','Notice of Identification','Notice of Contract','Statement of Account','Satisfaction of Claim of Lien','Satisfaction of Notice of Contract','Stop Payment Notice','Money Owed'];
function Select({label,value,options,onChange}:{label:string;value:unknown;options:JobOption[];onChange:(value:string)=>void}){return <label className={styles.field}><span>{label}</span><select value={String(value??'')} onChange={e=>onChange(e.target.value)}><option value=""/>{options.map(o=><option key={o.id} value={o.id}>{o.label}</option>)}</select></label>}
function Field({label,value='',onChange}:{label:string;value?:unknown;onChange?:(value:string)=>void}){return <label className={styles.field}><span>{label}</span><input readOnly={!onChange} value={String(value??'')} onChange={e=>onChange?.(e.target.value)}/></label>}
export function PartyNamePicker({kind,name,options,onPick,onType}:{kind:string;name:string;options:JobOption[];onPick:(option:JobOption)=>void;onType:(value:string)=>void}){
 const [open,setOpen]=useState(false);const [query,setQuery]=useState('');const root=useRef<HTMLDivElement>(null);
 useEffect(()=>{function close(event:MouseEvent){if(!root.current?.contains(event.target as Node))setOpen(false)}document.addEventListener('mousedown',close);return()=>document.removeEventListener('mousedown',close)},[]);
 const term=query.trim().toLowerCase();const rows=options.filter(option=>!term||`${option.label} ${option.street??''}`.toLowerCase().includes(term));
 return <div className={styles.partyNameField}><span>Name</span><div className={styles.partyPicker} ref={root}><div className={styles.partyPickerControl}><input role="combobox" aria-label={`${kind} name`} aria-expanded={open} aria-controls={`${kind}-party-list`} value={name} onFocus={()=>{setQuery('');setOpen(true)}} onChange={event=>{setQuery(event.target.value);onType(event.target.value);setOpen(true)}} onKeyDown={event=>{if(event.key==='Escape')setOpen(false);if(event.key==='ArrowDown'){event.preventDefault();setOpen(true);root.current?.querySelector<HTMLButtonElement>('[role=option]')?.focus()}}}/><button type="button" aria-label={`Open ${kind} name list`} onClick={()=>setOpen(value=>!value)}>⌄</button></div>{open&&<div id={`${kind}-party-list`} className={styles.partyDropdown} role="listbox"><div className={styles.partyDropdownHeader}><span>Name</span><span>Street</span></div><div className={styles.partyDropdownRows}>{rows.map(option=><button type="button" role="option" aria-selected={name===option.label} key={option.id} onClick={()=>{onPick(option);setQuery('');setOpen(false)}}><span>{option.label}</span><span>{option.street??''}</span></button>)}{!rows.length&&<div className={styles.partyDropdownEmpty}>No matching names</div>}</div></div>}</div></div>
}
function Party({title,kind,options,cities,current,onSave}:{title:string;kind:string;options:JobOption[];cities:JobOption[];current?:JobOption;onSave:(body:Record<string,unknown>)=>Promise<unknown>}){
 const [party,setParty]=useState(current);const [name,setName]=useState(current?.label??'');const [street,setStreet]=useState(current?.street??'');const [city,setCity]=useState(current?.cityId??null);const [zip,setZip]=useState(current?.zip??'');
 function pick(value:string){const next=options.find(o=>o.id===Number(value));setParty(next);setName(next?.label??'');setStreet(next?.street??'');setCity(next?.cityId??null);setZip(next?.zip??'');}
 return <fieldset><legend>{title}</legend><PartyNamePicker kind={kind} name={name} options={options} onPick={option=>pick(String(option.id))} onType={value=>{setName(value);setParty(undefined)}}/><Field label="Street" value={street} onChange={setStreet}/><Select label="City, State" value={city} options={cities} onChange={value=>setCity(value?Number(value):null)}/><Field label="Zip" value={zip} onChange={setZip}/><button onClick={()=>void onSave({action:'party',kind,name,street,cityId:city,zip,...(kind==='gc'?{masterId:party?.id}:{partyId:party?.id})})}>Save {kind==='gc'?'GC':kind==='owner'?'Owner':'Bank / MTG / Financier'} to Job</button><p>Or</p><button onClick={()=>{setParty(undefined);setName('');setStreet('');setCity(null);setZip('');}}>Add New {kind==='gc'?'GC':kind==='owner'?'Owner':'Bank / MTG / Financier'} to Job</button></fieldset>;
}
function addProjectLength(start:string,length?:JobOrderOption){if(!start||!length)return '';const end=new Date(`${start}T00:00:00Z`);const count=Number(length.intervalCount??0);const shiftMonths=(months:number)=>{const day=end.getUTCDate();end.setUTCDate(1);end.setUTCMonth(end.getUTCMonth()+months);const lastDay=new Date(Date.UTC(end.getUTCFullYear(),end.getUTCMonth()+1,0)).getUTCDate();end.setUTCDate(Math.min(day,lastDay))};switch(length.intervalCode){case'd':end.setUTCDate(end.getUTCDate()+count);break;case'ww':end.setUTCDate(end.getUTCDate()+count*7);break;case'm':shiftMonths(count);break;case'yyyy':shiftMonths(count*12);break;case'q':shiftMonths(count*3);break;case'y':end.setUTCDate(end.getUTCDate()+count);break;default:return '';}end.setUTCDate(end.getUTCDate()-1);return end.toISOString().slice(0,10)}
function JobOrderTab({data,draft,change,onWccHistory,onPostHistory,onRepost}:{data:JobWorkflow;draft:JobSiteData;change:(key:string,value:string|number|boolean|null)=>void;onWccHistory:()=>void;onPostHistory:()=>void;onRepost:()=>void}){
 const length=data.projectLengths.find(option=>option.id===Number(draft.ProjectLengthID));const date=(key:string)=>String(draft[key]??'');const flag=(label:string,key:string)=><label className={styles.orderCheck}>{label}<input type="checkbox" checked={Boolean(draft[key])} onChange={event=>change(key,event.target.checked)}/></label>;
 return <div className={styles.jobOrder}>
  <div className={styles.jobOrderMain}>
   <div className={styles.orderDateFields}><label><span>Start Date</span><input type="date" value={date('StartDate')} onChange={event=>{const start=event.target.value;change('StartDate',start||null);let selected=length;if(!selected){selected=data.projectLengths.find(option=>option.id===4);if(selected)change('ProjectLengthID',selected.id);}change('EndDate',addProjectLength(start,selected)||null)}}/></label><label><span>Est. Length</span><select value={String(draft.ProjectLengthID??'')} onChange={event=>{const selected=data.projectLengths.find(option=>option.id===Number(event.target.value));change('ProjectLengthID',selected?.id??null);change('EndDate',addProjectLength(date('StartDate'),selected)||null)}}><option value=""/>{data.projectLengths.map(option=><option key={option.id} value={option.id}>{option.label}</option>)}</select></label><label><span>End Date</span><input type="date" value={date('EndDate')} onChange={event=>change('EndDate',event.target.value||null)}/></label></div>
   <div className={styles.orderWcc}><label><span>Job WC Code</span><select value={String(draft.ProjectWCCID??'')} onChange={event=>change('ProjectWCCID',event.target.value?Number(event.target.value):null)}><option value=""/>{data.jobWccs.map(option=><option key={option.id} value={option.id}>{option.label}{option.active?'':' (Inactive)'}</option>)}</select></label><button onClick={onWccHistory}>History</button></div>
   <div className={styles.orderFlags}>{flag('OCIP Job','OCIPJob')}{flag('Rate Job','RateJob')}{flag('Shift Differential','ShiftDifferential')}{flag('Job Being Manned','JobBeingManned')}</div>
   <div className={styles.laborRates}><strong>Labor Wanted</strong><strong>Qty</strong><strong>Note</strong>{(['A','B','C'] as const).map(rate=><Fragment key={rate}><span>{rate} Rate</span><input aria-label={`${rate} rate quantity`} type="number" value={String(draft[`${rate}RateQty`]??'')} onChange={event=>change(`${rate}RateQty`,event.target.value?Number(event.target.value):null)}/><input aria-label={`${rate} rate note`} value={String(draft[`${rate}RateNote`]??'')} onChange={event=>change(`${rate}RateNote`,event.target.value)}/></Fragment>)}</div>
   <div className={styles.orderRule}>=============================================================================================</div>
   <div className={styles.orderExpense}><label><span>Expense Type</span><select value={String(draft.ExpenseTypeID??'')} onChange={event=>change('ExpenseTypeID',event.target.value?Number(event.target.value):null)}><option value=""/>{data.expenseTypes.map(option=><option key={option.id} value={option.id}>{option.label}{option.active?'':' (Inactive)'}</option>)}</select></label>{flag('Ignore Auto WCC Per Diem Rate','IgnoreAutoWCCPerDiemRate')}<label><span>Expense Pay Rate</span><input type="number" step="0.01" value={String(draft.ExpensePayRate??'')} onChange={event=>change('ExpensePayRate',event.target.value?Number(event.target.value):null)}/></label><label><span>Expense Bill Rate</span><input type="number" step="0.01" value={String(draft.ExpenseBillRate??'')} onChange={event=>change('ExpenseBillRate',event.target.value?Number(event.target.value):null)}/></label>{flag('Exclude Sales Tax','ExcludeSalesTax')}{flag('Exclude from Directions','ProjectExcludeFromDirections')}</div>
   <label className={styles.orderNote}><span>Job Note</span><textarea value={String(draft.JobNote??'')} onChange={event=>change('JobNote',event.target.value)}/></label>
  </div>
  <aside className={styles.orderPost}><button className={styles.repostButton} onClick={onRepost}>Re Post Job</button><div className={styles.postUser}><span>User</span><input readOnly value={String(draft.ProjectEntryUserName??'')}/></div><div className={styles.postDate}><span>Date</span><input readOnly value={String(draft.ProjectEntryDate??'')}/></div><div className={styles.postType}><span>Post Type</span><input readOnly value={String(draft.PostType??'')}/></div><label className={`${styles.orderCheck} ${styles.postHide}`}>Hide Post<input type="checkbox" checked={Boolean(draft.HidePost)} onChange={event=>change('HidePost',event.target.checked)}/></label><button className={styles.postHistoryButton} onClick={onPostHistory}>Post History</button></aside>
  <p className={styles.orderWarning}>4 Questions need a Yes or No Answer. When Shift Differential is answered yes it automatically puts an increase of 10% on top of all Pay, Bill Rates and Referral Rates on this Job. We need to talk about this</p>
 </div>
}
function ContactsTab({contacts,onSave,onDelete}:{contacts:JobSiteData[];onSave:(body:Record<string,unknown>)=>Promise<boolean>;onDelete:(id:number)=>Promise<boolean>}){
 const rowId=(row:JobSiteData):number|string=>typeof row.id==='string'||typeof row.id==='number'?row.id:'new';
 const emptyContact=():JobSiteData=>({id:'new',FName:'',LName:'',Role:'',Phone:'',Cell:'',Email:'',Notes:'',Sort:contacts.length+1});const [rows,setRows]=useState<JobSiteData[]>([...contacts,emptyContact()]);const [selected,setSelected]=useState<number|string|null>('new');
 useEffect(()=>{setRows([...contacts,{id:'new',FName:'',LName:'',Role:'',Phone:'',Cell:'',Email:'',Notes:'',Sort:contacts.length+1}]);if(typeof selected==='number'&&!contacts.some(row=>Number(row.id)===selected))setSelected('new')},[contacts]);
 const active=rows.find(row=>row.id===selected);function update(id:number|string,key:string,value:string){setRows(current=>current.map(row=>row.id===id?{...row,[key]:key==='Sort'?(value===''?null:Number(value)):value}:row))}
 function add(){setSelected('new')}
 async function save(){if(!active)return;const fields={FName:String(active.FName??''),LName:String(active.LName??''),Role:String(active.Role??''),Phone:String(active.Phone??''),Cell:String(active.Cell??''),Email:String(active.Email??''),Notes:String(active.Notes??''),Sort:active.Sort===null?null:Number(active.Sort)};if(await onSave({action:'contact-save',contactId:active.id==='new'?null:Number(active.id),fields}))setSelected(null)}
 async function remove(){if(typeof selected!=='number')return;if(window.confirm('Delete this job contact?')&&await onDelete(selected))setSelected(null)}
 const columns:[string,string][]=[['FName','FName'],['LName','LName'],['Role','Role'],['Phone','Phone'],['Cell','Cell'],['Email','Email'],['Notes','Notes'],['Sort','Sort']];
 return <div className={styles.contactsTab}><div className={styles.contactsToolbar}><button onClick={add}>New Contact</button><button disabled={!active} onClick={()=>void save()}>Save Contact</button><button disabled={typeof selected!=='number'} onClick={()=>void remove()}>Delete Contact</button></div><div className={styles.contactsGrid}><table><colgroup><col className={styles.contactSelector}/>{columns.map(([key])=><col key={key} className={styles[`contactCol${key}`]}/>)}</colgroup><thead><tr><th className={styles.contactSelector}></th>{columns.map(([key,label])=><th key={key}>{label}<span>⌄</span></th>)}</tr></thead><tbody>{rows.map(row=><tr key={String(row.id)} aria-selected={selected===rowId(row)} onClick={()=>setSelected(rowId(row))}><th className={styles.contactSelector}>{rowId(row)==='new'?'*':''}</th>{columns.map(([key])=><td key={key}><input aria-label={key} value={String(row[key]??'')} onFocus={()=>setSelected(rowId(row))} onChange={event=>update(rowId(row),key,event.target.value)}/></td>)}</tr>)}</tbody></table></div><footer className={styles.contactsFooter}>Record: {selected==='new'?`${contacts.length+1} of ${contacts.length+1}`:`${rows.findIndex(row=>rowId(row)===selected)+1} of ${contacts.length}`} <button aria-label="Previous contact" onClick={()=>setSelected(rows[0]?rowId(rows[0]):'new')}>◀</button><button aria-label="Next contact" onClick={()=>setSelected(rows.at(-1)?rowId(rows.at(-1)!):'new')}>▶</button><span>No Filter</span><input aria-label="Search contacts" placeholder="Search" onChange={event=>{const term=event.target.value.toLowerCase();const match=rows.find(row=>columns.some(([key])=>String(row[key]??'').toLowerCase().includes(term)));if(match)setSelected(rowId(match))}}/></footer></div>
}
function CertifiedPayrollTab({rows,titles,cities,draft,change,onSave,onDelete}:{rows:JobSiteData[];titles:JobOption[];cities:JobOption[];draft:JobSiteData;change:(key:string,value:string|number|boolean|null)=>void;onSave:(body:Record<string,unknown>)=>Promise<boolean>;onDelete:(id:number)=>Promise<boolean>}){
 const [items,setItems]=useState<JobSiteData[]>([...rows,{id:'new',Title:'',Name:'',ContactPerson:'',Street:'',CityID:null,Zip:'',Qty:null,NeedsReport:''}]);const [selected,setSelected]=useState<number|string|null>('new');
 useEffect(()=>{setItems([...rows,{id:'new',Title:'',Name:'',ContactPerson:'',Street:'',CityID:null,Zip:'',Qty:null,NeedsReport:''}]);if(typeof selected==='number'&&!rows.some(row=>Number(row.id)===selected))setSelected('new')},[rows]);
 const rowId=(row:JobSiteData):number|string=>typeof row.id==='string'||typeof row.id==='number'?row.id:'new';const active=items.find(row=>rowId(row)===selected);
 function update(id:number|string,key:string,value:string){setItems(current=>current.map(row=>rowId(row)===id?{...row,[key]:key==='CityID'?(value?Number(value):null):key==='Qty'?(value?Number(value):null):value}:row))}
 async function save(){if(!active)return;const fields={Title:String(active.Title??''),Name:String(active.Name??''),ContactPerson:String(active.ContactPerson??''),Street:String(active.Street??''),CityID:active.CityID===null?null:Number(active.CityID),Zip:String(active.Zip??''),Qty:active.Qty===null?null:Number(active.Qty),NeedsReport:String(active.NeedsReport??'')};if(await onSave({action:'certified-payroll-save',rowId:active.id==='new'?null:Number(active.id),fields}))setSelected(null)}
 async function remove(){if(typeof selected!=='number')return;if(window.confirm('Delete this certified payroll recipient?')&&await onDelete(selected))setSelected('new')}
 const columns:[string,string][]=[['Title','Title'],['Name','Name'],['ContactPerson','Contact Person'],['Street','Street'],['CityID','City, State'],['Zip','Zip'],['Qty','Qty of Reports']];
 return <div className={styles.certifiedPayrollTab}><div className={styles.certifiedPayrollHeader}><label>Awarding Authority&apos;s Name<input value={String(draft.AwardingAuthorityName??'')} onChange={event=>change('AwardingAuthorityName',event.target.value)}/></label><label>Min. Wage Rate Sheet No.<input value={String(draft.MinWageRateSheetNumber??'')} onChange={event=>change('MinWageRateSheetNumber',event.target.value)}/></label><label>General Contractor<input value={String(draft.CertifiedPayrollGC??'')} onChange={event=>change('CertifiedPayrollGC',event.target.value)}/></label></div><h3>Please send reports with original signatures to:</h3><div className={styles.contactsGrid}><table><colgroup><col className={styles.contactSelector}/><col className={styles.cpTitle}/><col className={styles.cpName}/><col className={styles.cpContact}/><col className={styles.cpStreet}/><col className={styles.cpCity}/><col className={styles.cpZip}/><col className={styles.cpQty}/></colgroup><thead><tr><th className={styles.contactSelector}></th>{columns.map(([key,label])=><th key={key}>{label}<span>⌄</span></th>)}</tr></thead><tbody>{items.map(row=><tr key={String(row.id)} aria-selected={selected===rowId(row)} onClick={()=>setSelected(rowId(row))}><th className={styles.contactSelector}>{rowId(row)==='new'?'*':''}</th>{columns.map(([key])=><td key={key}>{key==='Title'?<select aria-label={key} value={String(row.Title??'')} onFocus={()=>setSelected(rowId(row))} onChange={event=>update(rowId(row),key,event.target.value)}><option value=""/>{titles.map(option=><option key={option.id} value={option.label}>{option.label}</option>)}</select>:key==='CityID'?<select aria-label={key} value={String(row.CityID??'')} onFocus={()=>setSelected(rowId(row))} onChange={event=>update(rowId(row),key,event.target.value)}><option value=""/>{cities.map(option=><option key={option.id} value={option.id}>{option.label}</option>)}</select>:<input aria-label={key} type={key==='Qty'?'number':'text'} value={String(row[key]??'')} onFocus={()=>setSelected(rowId(row))} onChange={event=>update(rowId(row),key,event.target.value)}/>}</td>)}</tr>)}</tbody></table></div><div className={styles.certifiedPayrollActions}><button onClick={()=>setSelected('new')}>New Recipient</button><button disabled={!active} onClick={()=>void save()}>Save Recipient</button><button disabled={typeof selected!=='number'} onClick={()=>void remove()}>Delete Recipient</button><span>Needs Report</span><input aria-label="Needs Report" value={String(active?.NeedsReport??'')} onChange={event=>active&&update(rowId(active),'NeedsReport',event.target.value)}/></div><footer className={styles.contactsFooter}>Record: {selected==='new'?`${rows.length+1} of ${rows.length+1}`:`${items.findIndex(row=>rowId(row)===selected)+1} of ${rows.length}`} <button aria-label="Previous recipient" onClick={()=>setSelected(items[0]?rowId(items[0]):'new')}>◀</button><button aria-label="Next recipient" onClick={()=>setSelected(items.at(-1)?rowId(items.at(-1)!):'new')}>▶</button><span>No Filter</span><input aria-label="Search recipients" placeholder="Search" onChange={event=>{const term=event.target.value.toLowerCase();const match=items.find(row=>columns.some(([key])=>String(row[key]??'').toLowerCase().includes(term)));if(match)setSelected(rowId(match))}}/></footer></div>
}
function DirectionsTab({jobId,salesmen,job}:{jobId:number;salesmen:JobSiteData[];job:Record<string,unknown>}){
 const [employees,setEmployees]=useState<JobSiteData[]>([]);const [selectedSalesmen,setSelectedSalesmen]=useState<number[]>([]);const [selectedEmployees,setSelectedEmployees]=useState<number[]>([]);const [includeEmployeeInfo,setIncludeEmployeeInfo]=useState(false);const [preview,setPreview]=useState(false);const [busy,setBusy]=useState(false);
 async function searchEmployees(){const term=window.prompt('Search employees by first name, last name, email, or mobile phone:');if(!term?.trim())return;setBusy(true);try{const response=await fetch(`/api/jobs/${jobId}/directions?search=${encodeURIComponent(term.trim())}`);const result=await response.json();if(!response.ok)throw Error(result.error??'Employee search failed');setEmployees(result.data as JobSiteData[]);setSelectedEmployees([])}catch(error){window.alert(error instanceof Error?error.message:'Employee search failed')}finally{setBusy(false)}}
 function toggle(list:number[],set:(value:number[])=>void,id:number){set(list.includes(id)?list.filter(item=>item!==id):[...list,id])}
 const chosenSalesmen=salesmen.filter(row=>selectedSalesmen.includes(Number(row.id)));const chosenEmployees=employees.filter(row=>selectedEmployees.includes(Number(row.id)));
 const jobName=String(job.jobName??'');const directions=[`Customer: ${String(job.customerName??'')}`,`Job: ${jobName}`,`Address: ${String(job.street??'')}, ${String(job.city??'')}, ${String(job.state??'')} ${String(job.zip??'')}`,`Start time: ${String(job.startTime??'')}`,`Foreman: ${String(job.foreman??'')} ${String(job.foremanPhone??'')}`,String(job.notes??'')].filter(Boolean);
 if(includeEmployeeInfo&&chosenEmployees.length)directions.push(`Employees: ${chosenEmployees.map(row=>`${row.Name}${row.MobilePhone?` (${row.MobilePhone})`:''}`).join(', ')}`);
 const body=directions.join('\n');const selectedEmail=[...chosenSalesmen.map(row=>String(row.Email??'')),...chosenEmployees.map(row=>String(row.Email??''))].filter(Boolean).join(';');const selectedText=[...chosenSalesmen.map(row=>String(row.TextAddress??'')),...chosenEmployees.map(row=>String(row.TextAddress??''))].filter(Boolean).join(',');
 function email(){if(!selectedEmail){window.alert('Select at least one recipient with an email address.');return}window.location.href=`mailto:${encodeURIComponent(selectedEmail)}?subject=${encodeURIComponent(`Directions: ${jobName}`)}&body=${encodeURIComponent(body)}`}
 function text(){if(!selectedText){window.alert('Select at least one recipient with a text address.');return}window.location.href=`sms:${encodeURIComponent(selectedText)}?body=${encodeURIComponent(body)}`}
 return <div className={styles.directionsTab}><h3>Directions:</h3><div className={styles.directionGrids}><section><h4>Select Salesmen (click in Select column)</h4><div className={styles.directionGrid}><table><thead><tr><th>Salesman</th><th>Has Email</th><th>Has Text</th><th>Select</th></tr></thead><tbody>{salesmen.map(row=><tr key={String(row.id)} aria-selected={selectedSalesmen.includes(Number(row.id))}><td>{String(row.Name??'')}</td><td><input type="checkbox" readOnly checked={Boolean(row.HasEmail)}/></td><td><input type="checkbox" readOnly checked={Boolean(row.HasText)}/></td><td><input aria-label={`Select ${String(row.Name??'salesman')}`} type="checkbox" checked={selectedSalesmen.includes(Number(row.id))} onChange={()=>toggle(selectedSalesmen,setSelectedSalesmen,Number(row.id))}/></td></tr>)}</tbody></table></div><button onClick={()=>setSelectedSalesmen([])}>Clear Select</button></section><section><h4>Select Employees (use Search, then click in Select column)</h4><div className={styles.directionGrid}><table><thead><tr><th>Employee</th><th>Has Email</th><th>Has Text</th><th>Select</th></tr></thead><tbody>{employees.map(row=><tr key={String(row.id)} aria-selected={selectedEmployees.includes(Number(row.id))}><td>{String(row.Name??'')}</td><td><input type="checkbox" readOnly checked={Boolean(row.HasEmail)}/></td><td><input type="checkbox" readOnly checked={Boolean(row.HasText)}/></td><td><input aria-label={`Select ${String(row.Name??'employee')}`} type="checkbox" checked={selectedEmployees.includes(Number(row.id))} onChange={()=>toggle(selectedEmployees,setSelectedEmployees,Number(row.id))}/></td></tr>)}</tbody></table>{!employees.length&&<div className={styles.directionGridEmpty}/>}</div><div className={styles.directionButtons}><button disabled={busy} onClick={()=>void searchEmployees()}>{busy?'Searching…':'Search'}</button><button onClick={()=>setSelectedEmployees([])}>Clear Select</button><button disabled={!selectedEmployees.length} onClick={()=>{setSelectedEmployees([]);setEmployees([])}}>Delete Selected</button></div></section></div><div className={styles.includeEmployeeInfo}><span>Include Employee Information in the Directions?</span><label>Yes<input type="radio" name="includeEmployeeInfo" checked={includeEmployeeInfo} onChange={()=>setIncludeEmployeeInfo(true)}/></label><label>No<input type="radio" name="includeEmployeeInfo" checked={!includeEmployeeInfo} onChange={()=>setIncludeEmployeeInfo(false)}/></label></div><div className={styles.directionActions}><button onClick={()=>setPreview(true)}>View</button><button onClick={()=>{setPreview(true);setTimeout(()=>window.print(),250)}}>Print</button><button disabled={!selectedEmail} onClick={email}>Email</button><button disabled={!selectedText} onClick={text}>Text</button></div>{preview&&<div className={styles.directionPreviewOverlay} role="dialog" aria-modal="true"><article className={styles.directionPreview}><header><h2>Directions</h2><button onClick={()=>setPreview(false)}>Close</button></header><p><strong>{String(job.customerName??'')}</strong></p><p><strong>{jobName}</strong></p><p>{String(job.street??'')}<br/>{String(job.city??'')}, {String(job.state??'')} {String(job.zip??'')}</p><p>Start time: {String(job.startTime??'')}</p><p>Foreman: {String(job.foreman??'')} {String(job.foremanPhone??'')}</p><p>{String(job.notes??'')}</p>{includeEmployeeInfo&&<div><h3>Employees</h3>{chosenEmployees.map(row=><p key={String(row.id)}>{String(row.Name??'')} {String(row.MobilePhone??'')} {String(row.Email??'')}</p>)}</div>}</article></div>}</div>
}
function NoticeIdentificationTab({jobId,data,onSave,onReport}:{jobId:string|number;data:JobWorkflow;onSave:(body:Record<string,unknown>)=>Promise<boolean>;onReport:()=>void}){
 const [form,setForm]=useState<JobSiteData>(data.noi);const [busy,setBusy]=useState(false);const [message,setMessage]=useState('');
 useEffect(()=>setForm(data.noi),[data.noi]);
 const set=(key:string,value:string|number|null)=>setForm(old=>({...old,[key]:value}));
 const text=(label:string,key:string,readOnly=false)=><label className={styles.noiField}><span>{label}</span><input value={String(form[key]??'')} readOnly={readOnly} onChange={e=>set(key,e.target.value)}/></label>;
 const select=(label:string,key:string,options:JobOption[])=><label className={styles.noiField}><span>{label}</span><select value={String(form[key]??'')} onChange={e=>set(key,e.target.value?Number(e.target.value):null)}><option value=""/>{options.map(option=><option key={option.id} value={option.id}>{option.label}</option>)}</select></label>;
 async function chooseParty(kind:'gc'|'owner'|'bank',option:JobOption){setBusy(true);setMessage('Loading party details…');try{const sameJob=String(option.projectId??jobId)===String(jobId);const ok=await onSave({action:'party',kind,name:option.label,street:option.street??'',cityId:option.cityId??null,zip:option.zip??'',...(kind==='gc'?{masterId:option.id}:sameJob?{partyId:option.id}:{copyFromId:option.id})});setMessage(ok?'Party loaded from the database.':'Party could not be loaded.');}finally{setBusy(false);}}
 async function save():Promise<boolean>{setBusy(true);setMessage('Saving Notice of Identification…');try{for(const [kind,prefix,options] of [['owner','Owner',data.owners],['gc','GC',data.contractors],['bank','Bank',data.banks]] as const){const name=String(form[`${prefix}Name`]??'').trim();if(!name)continue;const option=options.find(item=>item.label===name);if(option){const sameJob=String(option.projectId??jobId)===String(jobId);const ok=await onSave({action:'party',kind,name:option.label,street:option.street??'',cityId:option.cityId??null,zip:option.zip??'',...(kind==='gc'?{masterId:option.id}:sameJob?{partyId:option.id}:{copyFromId:option.id})});if(!ok)return false;}else{const ok=await onSave({action:'party',kind,name,street:String(form[`${prefix}Street`]??''),cityId:form[`${prefix}CityID`]??null,zip:String(form[`${prefix}Zip`]??'')});if(!ok)return false;}}
 const fields:Record<string,unknown>={};const ids=['NOICustomerRegMailResponseID','NOISignedByID','StatusOfNOIID','LegalStateCountyID'];for(const key of ['CustomerContact','CustomerPhone','CustomerEmail','CustomerNotes','NOICustomerCertMailNumber','NOICustomerRegMailResponseID','NOIDateSigned','NOISignedByID','StatusOfNOIID','NOINotes','NoticeOfContractContractWith','LegalStateCountyID','NOICustomerDocHLink','NOICustomerDocCMTrackerHLink','NOIOwnerDocHLink','NOIOwnerDocCMTrackerHLink','NOIGCDocHLink','NOIGCDocCMTrackerHLink','NOIBMFDocHLink','NOIBMFDocCMTrackerHLink'])if(key in form)fields[key]=ids.includes(key)?form[key]??null:key==='NOIDateSigned'?String(form[key]??'').slice(0,10)||null:String(form[key]??'');
 const parties={owner:{contact:String(form.OwnerContact??''),phone:String(form.OwnerPhone??''),email:String(form.OwnerEmail??''),notes:String(form.OwnerNotes??''),certMail:String(form.OwnerCertMailNumber??''),responseId:form.OwnerRegMailResponseID??null},gc:{contact:String(form.GCContact??''),phone:String(form.GCPhone??''),email:String(form.GCEmail??''),notes:String(form.GCNotes??''),certMail:String(form.GCCertMailNumber??''),responseId:form.GCRegMailResponseID??null},bank:{contact:String(form.BankContact??''),phone:String(form.BankPhone??''),email:String(form.BankEmail??''),notes:String(form.BankNotes??''),certMail:String(form.BankCertMailNumber??''),responseId:form.BankRegMailResponseID??null}};
 const ok=await onSave({action:'noi-save',fields,parties});setMessage(ok?'Notice of Identification details saved.':'Save failed; review the message below.');return ok;}catch(error){setMessage(error instanceof Error?error.message:'Notice of Identification save failed.');return false;}finally{setBusy(false);}}
 const party=(title:string,kind:'gc'|'owner'|'bank',prefix:'Owner'|'GC'|'Bank',options:JobOption[])=>{const current=String(form[`${prefix}Name`]??'');const known=options.some(option=>option.label===current);return <section className={styles.noiParty} key={kind}><header><strong>{title}</strong><button type="button" onClick={()=>document.querySelector<HTMLInputElement>(`#noi-${kind}-name input[role=combobox]`)?.focus()}>Edit List ({options.length})</button></header><div className={styles.noiName}><span>Name</span><div id={`noi-${kind}-name`}><PartyNamePicker kind={`noi-${kind}`} name={current} options={options} onPick={option=>void chooseParty(kind,option)} onType={value=>{set(`${prefix}Name`,value);if(value!==current){for(const key of ['Street','Zip','Contact','Phone','Email','Notes','CertMailNumber'])set(`${prefix}${key}`,'');set(`${prefix}CityID`,null);set(`${prefix}RegMailResponseID`,null);}}}/></div></div>{text('Street',`${prefix}Street`,known)}{known?text('City, State',`${prefix}City`,true):select('City, State',`${prefix}CityID`,data.cities)}{text('Zip',`${prefix}Zip`,known)}{text('Contact Person',`${prefix}Contact`)}{text('Contact Phone',`${prefix}Phone`)}{text('Contact Email',`${prefix}Email`)}<label className={styles.noiField}><span>Notes</span><textarea value={String(form[`${prefix}Notes`]??'')} onChange={e=>set(`${prefix}Notes`,e.target.value)}/></label>{text('Certified Mail #',`${prefix}CertMailNumber`)}{select('Reg Mail Resp',`${prefix}RegMailResponseID`,data.noiResponses)}{documentControl(`${prefix}Document`,`${prefix==='Owner'?'NOIOwnerDocHLink':prefix==='GC'?'NOIGCDocHLink':'NOIBMFDocHLink'}`)}{documentControl('Cert Mail Trckr',`${prefix==='Owner'?'NOIOwnerDocCMTrackerHLink':prefix==='GC'?'NOIGCDocCMTrackerHLink':'NOIBMFDocCMTrackerHLink'}`)}</section>};
 function documentControl(label:string,key:string){const value=String(form[key]??'');return <div className={styles.noiDocument}><span>{label}</span><input aria-label={label} value={value} onChange={e=>set(key,e.target.value)}/>{value&&/^https?:\/\//i.test(value)&&<a href={value} target="_blank" rel="noreferrer">Open</a>}</div>}
 return <div className={styles.noiTab}>
 <div className={styles.noiParties}>
 <section className={styles.noiParty}><header><strong>Customer Information</strong></header>{text('Name','CustomerName',true)}{text('Street','CustomerStreet',true)}{text('City, State','CustomerCity',true)}{text('Zip','CustomerZip',true)}{text('Contact Person','CustomerContact')}{text('Contact Phone','CustomerPhone')}{text('Contact Email','CustomerEmail')}<label className={styles.noiField}><span>Notes</span><textarea value={String(form.CustomerNotes??'')} onChange={e=>set('CustomerNotes',e.target.value)}/></label>{text('Certified Mail #','CustomerCertMailNumber')}{select('Reg Mail Resp','CustomerRegMailResponseID',data.noiResponses)}{documentControl('NOI Document','NOICustomerDocHLink')}{documentControl('Cert Mail Trckr','NOICustomerDocCMTrackerHLink')}</section>
 {party('Owner Information','owner','Owner',data.owners)}{party('General Contractor Information','gc','GC',data.contractors)}{party('Bank / MTG / Financier Information','bank','Bank',data.banks)}
 </div><div className={styles.noiLower}><section className={styles.noiFooterFields}><label className={styles.noiField}><span>Payroll Contract With</span><select value={String(form.NoticeOfContractContractWith??'')} onChange={e=>set('NoticeOfContractContractWith',e.target.value||'')}><option value=""/>{data.payrollCompanies.map(option=><option key={option.id} value={option.label}>{option.label}</option>)}</select></label><label className={styles.noiField}><span>Date Signed</span><input type="date" value={String(form.NOIDateSigned??'').slice(0,10)} onChange={e=>set('NOIDateSigned',e.target.value||'')}/></label><label className={styles.noiField}><span>User</span><input readOnly value={String(form.NOIDateSignedUserName??'')}/></label><label className={styles.noiField}><span>Date</span><input readOnly value={String(form.NOIDateSignedTimestamp??'')}/></label>{select('Signed By','NOISignedByID',data.salesmen.map(row=>({id:Number(row.id),label:String(row.Name??'')})))}{select('Status of NOI','StatusOfNOIID',data.noiStatuses)}<label className={styles.noiField}><span>User</span><input readOnly value={String(form.StatusOfNOIUserName??'')}/></label><label className={styles.noiField}><span>Date</span><input readOnly value={String(form.StatusOfNOITimestamp??'')}/></label>{select('Legal County','LegalStateCountyID',data.counties)}</section><label className={styles.noiGlobalNotes}><span>Notes</span><textarea value={String(form.NOINotes??'')} onChange={e=>set('NOINotes',e.target.value)}/></label><button type="button" className={styles.noiUsps} onClick={()=>window.open('https://tools.usps.com/go/TrackConfirmAction_input','_blank','noopener,noreferrer')}>USPS<br/>Track</button></div><div className={styles.noiActions}><button disabled={busy} onClick={()=>void save()}>{busy?'Saving…':'Save Notice Data'}</button><button disabled={busy} onClick={()=>void save().then(ok=>{if(ok)onReport()})}>Notice of Identification Report</button><span role="status">{message}</span></div>
 </div>
}
