function StopPaymentNoticeTab({data,draft,change,onSave,onReport}:{data:JobWorkflow;draft:JobSiteData;change:(key:string,value:string|number|boolean|null)=>void;onSave:(body:Record<string,unknown>)=>Promise<boolean>;onReport:()=>void}){
 const [editing,setEditing]=useState<Record<string,boolean>>({});
 const [parties,setParties]=useState({owner:{cert:String(data.noi.OwnerSPNCertMailNumber??''),response:String(data.noi.OwnerSPNRegMailResponseID??'')},gc:{cert:String(data.noi.GCSPNCertMailNumber??''),response:String(data.noi.GCSPNRegMailResponseID??'')}});
 useEffect(()=>setParties({owner:{cert:String(data.noi.OwnerSPNCertMailNumber??''),response:String(data.noi.OwnerSPNRegMailResponseID??'')},gc:{cert:String(data.noi.GCSPNCertMailNumber??''),response:String(data.noi.GCSPNRegMailResponseID??'')}}),[data]);
 const documentRow=(label:string,key:string)=><div className={styles.stopDoc}><span>{label}</span><input value={String(draft[key]??'')} onChange={e=>change(key,e.target.value)}/><button type="button" title="Open document" onClick={()=>{const value=String(draft[key]??'');if(value)window.open(value,'_blank','noopener,noreferrer')}}>⌕</button><button type="button" title="Enter document link" onClick={()=>{const value=window.prompt('Enter the document path or URL',String(draft[key]??''));if(value!==null)change(key,value)}}>📂</button><button type="button" title="Clear link" onClick={()=>change(key,'')}>×</button></div>;
 const party=(kind:'owner'|'gc',title:string)=>{const p=parties[kind];const prefix=kind==='owner'?'Owner':'GC';return <section className={styles.stopParty}><header><strong>{title}</strong><button type="button" onClick={()=>setEditing(current=>({...current,[kind]:!current[kind]}))}>{editing[kind]?'Cancel':'Edit'}</button></header><label><span>Certified Mail #</span><input readOnly={!editing[kind]} value={p.cert} onChange={e=>setParties(current=>({...current,[kind]:{...current[kind],cert:e.target.value}}))}/></label><label><span>Reg Mail Resp.</span><select disabled={!editing[kind]} value={p.response} onChange={e=>setParties(current=>({...current,[kind]:{...current[kind],response:e.target.value}}))}><option value=""/>{data.noiResponses.map(option=><option key={option.id} value={option.id}>{option.label}</option>)}</select></label>{documentRow('SPN Document',`SPN${prefix}DocHLink`)}{documentRow('Cert Mail Trckr',`SPN${prefix}DocCMTrackerHLink`)}{editing[kind]&&<button type="button" onClick={()=>void onSave({action:'spn-party-save',kind,cert:p.cert,responseId:p.response?Number(p.response):null}).then(ok=>ok&&setEditing(current=>({...current,[kind]:false})))}>Save</button>}</section>};
 return <div className={styles.stopPaymentTab}><div className={styles.stopParties}><section className={styles.stopParty}><header><strong>Customer Information</strong></header><label><span>Certified Mail #</span><input value={String(draft.SPNCustomerCertMailNumber??'')} onChange={e=>change('SPNCustomerCertMailNumber',e.target.value)}/></label><label><span>Reg Mail Resp.</span><select value={String(draft.SPNCustomerRegMailResponseID??'')} onChange={e=>change('SPNCustomerRegMailResponseID',e.target.value?Number(e.target.value):null)}><option value=""/>{data.noiResponses.map(option=><option key={option.id} value={option.id}>{option.label}</option>)}</select></label>{documentRow('SPN Document','SPNCustomerDocHLink')}{documentRow('Cert Mail Trckr','SPNCustomerDocCMTrackerHLink')}</section>{party('owner','Owner Information')}{party('gc','General Contractor Information')}</div><button className={styles.stopReport} type="button" onClick={onReport}>Stop Payment Notice Report</button></div>;
}
function MoneyOwedTab({data,draft,change,onSave,onReport}:{data:JobWorkflow;draft:JobSiteData;change:(key:string,value:string|number|boolean|null)=>void;onSave:(body:Record<string,unknown>)=>Promise<boolean>;onReport:()=>void}){
 const [editing,setEditing]=useState<Record<string,boolean>>({});
 const [partyMail,setPartyMail]=useState({owner:String(data.noi.OwnerMOCertMailNumber??''),gc:String(data.noi.GCMOCertMailNumber??'')});
 useEffect(()=>setPartyMail({owner:String(data.noi.OwnerMOCertMailNumber??''),gc:String(data.noi.GCMOCertMailNumber??'')}),[data]);
 const doc=(label:string,key:string)=><div className={styles.moneyDoc}><span>{label}</span><input value={String(draft[key]??'')} onChange={e=>change(key,e.target.value)}/><button type="button" title="Open document" onClick={()=>{const value=String(draft[key]??'');if(value)window.open(value,'_blank','noopener,noreferrer')}}>⌕</button><button type="button" title="Enter document path or URL" onClick={()=>{const value=window.prompt('Enter the document path or URL',String(draft[key]??''));if(value!==null)change(key,value)}}>📂</button><button type="button" title="Clear link" onClick={()=>change(key,'')}>×</button></div>;
 const party=(kind:'owner'|'gc',title:string)=>{const key=kind==='owner'?'Owner':'GC';return <section className={styles.moneyParty}><header><strong>{title}</strong><button type="button" onClick={()=>setEditing(value=>({...value,[kind]:!value[kind]}))}>{editing[kind]?'Cancel':'Edit'}</button></header><label><span>Certified Mail #</span><input readOnly={!editing[kind]} value={partyMail[kind]} onChange={e=>setPartyMail(value=>({...value,[kind]:e.target.value}))}/></label>{doc('MO Document',`MO${key}DocHLink`)}{editing[kind]&&<button type="button" onClick={()=>void onSave({action:'mo-party-save',kind,cert:partyMail[kind]}).then(ok=>ok&&setEditing(value=>({...value,[kind]:false})))}>Save</button>}</section>};
 function setReminderStart(value:string){change('MOReminderEmailStartDate',value||null);if(!value){change('MOReminderEmailNextDate',null);return;}const date=new Date(`${value}T12:00:00`);date.setDate(date.getDate()+30);change('MOReminderEmailNextDate',date.toISOString().slice(0,10));}
 function stopReminder(){if(!window.confirm('Clear the reminder dates and stop reminders for this job?'))return;change('MOReminderEmailStartDate',null);change('MOReminderEmailNextDate',null);}
 function resetReminder(){const current=String(draft.MOReminderEmailNextDate??'');if(!current)return;if(!window.confirm('Add 30 days to Next Date? Do this after the Money Owed report has been sent.'))return;const date=new Date(`${current.slice(0,10)}T12:00:00`);date.setDate(date.getDate()+30);change('MOReminderEmailNextDate',date.toISOString().slice(0,10));}
 return <div className={styles.moneyOwedTab}><div className={styles.moneyParties}><section className={styles.moneyParty}><header><strong>Customer Information</strong></header><label><span>Certified Mail #</span><input value={String(draft.MOCustomerCertMailNumber??'')} onChange={e=>change('MOCustomerCertMailNumber',e.target.value)}/></label>{doc('MO Document','MOCustomerDocHLink')}</section>{party('owner','Owner Information')}{party('gc','General Contractor Information')}</div><div className={styles.moneyDetails}><section className={styles.moneyDetailFields}><label><span>Payroll Contract With</span><select value={String(draft.NoticeOfContractContractWith??'')} onChange={e=>change('NoticeOfContractContractWith',e.target.value)}><option value=""/>{data.payrollCompanies.map(option=><option key={option.id} value={option.label}>{option.label}</option>)}</select></label><label><span>Date Signed</span><input type="date" value={String(draft.MODateSigned??'').slice(0,10)} onChange={e=>change('MODateSigned',e.target.value||null)}/></label><label><span>User</span><input readOnly value={String(draft.MODateSignedUserName??'')}/></label><label><span>Date</span><input readOnly value={String(draft.MODateSignedTimestamp??'')}/></label><label><span>Signed By</span><select value={String(draft.MOSignedByID??'')} onChange={e=>change('MOSignedByID',e.target.value?Number(e.target.value):null)}><option value=""/>{data.salesmen.map(row=><option key={String(row.id)} value={String(row.id)}>{String(row.Name??'')}</option>)}</select></label></section><label className={styles.moneyNotes}><span>Notes</span><textarea value={String(draft.MONotes??'')} onChange={e=>change('MONotes',e.target.value)}/></label></div><div className={styles.moneyReminder}><strong>30-Day Reminder Email | 040</strong><label><span>Start Date</span><input type="date" value={String(draft.MOReminderEmailStartDate??'').slice(0,10)} onChange={e=>setReminderStart(e.target.value)}/><button type="button" onClick={stopReminder}>Stop</button></label><label><span>Next Date</span><input type="date" value={String(draft.MOReminderEmailNextDate??'').slice(0,10)} onChange={e=>change('MOReminderEmailNextDate',e.target.value||null)}/><button type="button" onClick={resetReminder}>Reset</button></label></div><button className={styles.moneyReport} type="button" onClick={onReport}>Money Owed on This Job Report</button></div>;
}
function NoticeContractTab({job,data,onSave,onReport}:{job:JobDetail;data:JobWorkflow;onSave:(body:Record<string,unknown>)=>Promise<boolean>;onReport:()=>void}){
 const [form,setForm]=useState<JobSiteData>({...data.noi,BookPage:data.noi.BookPage??'',JobNote:data.site.JobNote??''});
 const [message,setMessage]=useState('');
 const [busy,setBusy]=useState(false);
 useEffect(()=>setForm({...data.noi,BookPage:data.noi.BookPage??'',JobNote:data.site.JobNote??''}),[data]);
 function change(key:string,value:string|number|boolean|null){setForm(current=>({...current,[key]:value}));}
 async function save(){setBusy(true);setMessage('Saving Notice of Contract...');try{const fields={NOCContractDate:form.NOCContractDateValue?String(form.NOCContractDateValue).slice(0,10):null,DateNotarized:form.DateNotarizedValue?String(form.DateNotarizedValue).slice(0,10):null,NOCSignedByID:form.NOCSignedByID?Number(form.NOCSignedByID):null,NOCIncludeMcLabor:Boolean(form.NOCIncludeMcLabor),NoticeOfContractContractWith:String(form.NoticeOfContractContractWith??''),BookPage:String(form.BookPage??''),LegalStateCountyID:form.LegalStateCountyID?Number(form.LegalStateCountyID):null,JobNote:String(form.JobNote??'')};const ok=await onSave({action:'save',fields});setMessage(ok?'Notice of Contract details saved.':'Save failed.');}finally{setBusy(false);}}
 const party=(title:string,keys:string[])=>{const kind=title==='Owner Information'?'owner':title==='General Contractor Information'?'gc':'bank';const prefix=kind==='owner'?'Owner':kind==='gc'?'GC':'Bank';const options=kind==='owner'?data.owners:kind==='gc'?data.contractors:data.banks;const name=String(data.noi[prefix+'Name']??'');const labels=['Name','Street','City, State','Zip','Contact Person','Contact Phone','Contact Email','Notes','Certified Mail #'];if(title==='Customer Information')return <section className={styles.noiParty}><header><strong>{title}</strong></header>{keys.map((key,index)=>key.toLowerCase().includes('notes')?<label className={styles.noiField} key={key}><span>{labels[index]}</span><textarea readOnly value={String(data.noi[key]??'')}/></label>:<Field key={key} label={labels[index]} value={data.noi[key]}/>)}</section>;return <section className={styles.noiParty} key={kind}><header><strong>{title}</strong><button type="button" onClick={()=>document.querySelector<HTMLInputElement>('#noc-'+kind+' input[role=combobox]')?.focus()}>Edit List ({options.length})</button></header><div className={styles.noiName}><span>Name</span><div id={'noc-'+kind}><PartyNamePicker kind={'noc-'+kind} name={String(form[prefix+'Name']??name)} options={options} onPick={option=>{void onSave({action:'party',kind,name:option.label,street:option.street??'',cityId:option.cityId??null,zip:option.zip??'',...(kind==='gc'?{masterId:option.id}:option.projectId===Number(job.jobId)?{partyId:option.id}:{copyFromId:option.id})});}} onType={value=>change(prefix+'Name',value)}/></div></div>{keys.slice(1).map((key,index)=>key.toLowerCase().includes('notes')?<label className={styles.noiField} key={key}><span>{labels[index+1]}</span><textarea value={String(form[key]??data.noi[key]??'')} onChange={e=>change(key,e.target.value)}/></label>:<Field key={key} label={labels[index+1]} value={form[key]??data.noi[key]}/>)}<Field label="NOC Document" value={kind==='owner'?'':kind==='gc'?'':kind==='bank'?'':data.documents[0]?.['Notice of Contract']??''}/><Field label="Cert Mail Trckr" value={form[prefix+'DocCMTrackerHLink']??''}/></section>};
 return <div className={styles.noiTab}><div className={styles.noiParties}>{party('Customer Information',['CustomerName','CustomerStreet','CustomerCity','CustomerZip','CustomerContact','CustomerPhone','CustomerEmail','CustomerNotes','CustomerCertMailNumber'])}{party('Owner Information',['OwnerName','OwnerStreet','OwnerCity','OwnerZip','OwnerContact','OwnerPhone','OwnerEmail','OwnerNotes','OwnerCertMailNumber'])}{party('General Contractor Information',['GCName','GCStreet','GCCity','GCZip','GCContact','GCPhone','GCEmail','GCNotes','GCCertMailNumber'])}{party('Bank / MTG / Financier Information',['BankName','BankStreet','BankCity','BankZip','BankContact','BankPhone','BankEmail','BankNotes','BankCertMailNumber'])}</div><div className={styles.nocLower}><div className={styles.nocFields}><label className={styles.noiField}><span>Date Signed</span><input type="date" value={String(form.NOCContractDateValue??'').slice(0,10)} onChange={e=>change('NOCContractDateValue',e.target.value||null)}/></label><label className={styles.noiField}><span>Payroll Contract With</span><select value={String(form.NoticeOfContractContractWith??'')} onChange={e=>change('NoticeOfContractContractWith',e.target.value)}><option value=""/>{data.payrollCompanies.map(o=><option key={o.id} value={o.label}>{o.label}</option>)}</select></label><label className={styles.noiField}><span>Date of Contract</span><input type="date" value={String(form.NOCContractDateValue??'').slice(0,10)} onChange={e=>change('NOCContractDateValue',e.target.value||null)}/></label><label className={styles.noiField}><span>Include MC Labor</span><input type="checkbox" checked={Boolean(form.NOCIncludeMcLabor)} onChange={e=>change('NOCIncludeMcLabor',e.target.checked)}/></label><Field label="Contract Amount" value={job.contractAmount}/><Field label="Total Payments" value={job.contractTotalPayments}/><Field label="Balance Owed" value={job.contractBalanceOwed}/><label className={styles.noiField}><span>Signed By</span><select value={String(form.NOCSignedByID??'')} onChange={e=>change('NOCSignedByID',e.target.value?Number(e.target.value):null)}><option value=""/>{data.salesmen.map(row=><option key={String(row.id)} value={String(row.id)}>{String(row.Name??'')}</option>)}</select></label><label className={styles.noiField}><span>Book / Page</span><input value={String(form.BookPage??'')} onChange={e=>change('BookPage',e.target.value)}/></label><label className={styles.noiField}><span>Legal County</span><select value={String(form.LegalStateCountyID??'')} onChange={e=>change('LegalStateCountyID',e.target.value?Number(e.target.value):null)}><option value=""/>{data.counties.map(o=><option key={o.id} value={o.id}>{o.label}</option>)}</select></label><label className={styles.noiField}><span>Date Notarized</span><input type="date" value={String(form.DateNotarizedValue??'').slice(0,10)} onChange={e=>change('DateNotarizedValue',e.target.value||null)}/></label></div><div className={styles.nocJobDates}><label>First Date on Job Site<input readOnly value={job.startDate}/></label><label>Last Date on Job Site<input readOnly value={job.endDate}/></label><button type="button" onClick={()=>setMessage('Job dates refreshed from the selected job.')}>Refresh</button></div><label className={styles.nocNotes}><span>Contract Notes</span><textarea value={String(form.JobNote??'')} onChange={e=>change('JobNote',e.target.value)}/></label><div className={styles.nocContracts}><strong>Customer Contracts</strong>{['AMP','GS','HDE','HSG','IPG','ISG','MLS'].map(code=><div key={code}><b>{code}</b><span/><button type="button" onClick={()=>setMessage('No saved '+code+' contract is linked to this job.')}>Open Contract</button></div>)}</div></div><div className={styles.noiActions}><button disabled={busy} onClick={()=>void save()}>{busy?'Saving…':'Save Notice Data'}</button><button disabled={busy} onClick={onReport}>Notice of Contract Report</button><span role="status">{message}</span></div></div>;
}

export function JobProfileScreen({job:initialJob,site:initial}:{job:JobDetail;site:JobWorkflow}){
 const [job,setJob]=useState(initialJob);const [selectedCustomerId,setSelectedCustomerId]=useState(initialJob.customerId);const [selectedJobId,setSelectedJobId]=useState(initialJob.jobId);
 const router=useRouter();const [data,setData]=useState(initial);const [draft,setDraft]=useState<JobSiteData>(initial.site);const [changes,setChanges]=useState<JobSiteData>({});const [tab,setTab]=useState('Site Data');const [message,setMessage]=useState('');const [busy,setBusy]=useState(false);const [instruction,setInstruction]=useState('');const [instructionName,setInstructionName]=useState('');const [dialog,setDialog]=useState<{title:string;rows:JobSiteData[]}|null>(null);const [historySearch,setHistorySearch]=useState('');const [menuState,setMenuState]=useState(job.state||'MA');const [ignoreWarnings,setIgnoreWarnings]=useState(false);const [accidentModal,setAccidentModal]=useState<string|null|undefined>(undefined);
 async function switchJob(nextId:string,confirmed=false){if(!nextId||nextId===job.jobId)return;if(!confirmed&&Object.keys(changes).length&&!window.confirm("Discard unsaved changes and switch jobs?")){return;}setBusy(true);setMessage("Loading job...");try{const [jobResponse,siteResponse]=await Promise.all([fetch(`/api/jobs/${encodeURIComponent(nextId)}`,{cache:"no-store"}),fetch(`/api/jobs/${encodeURIComponent(nextId)}/site`,{cache:"no-store"})]);const jobResult=await jobResponse.json();if(!jobResponse.ok||!jobResult.ok||!jobResult.data)throw Error(jobResult.error??"Could not load job.");if(!siteResponse.ok)throw Error("Could not load job details.");const workflow=await siteResponse.json() as JobWorkflow;setJob(jobResult.data as JobDetail);setSelectedCustomerId((jobResult.data as JobDetail).customerId);setSelectedJobId((jobResult.data as JobDetail).jobId);setData(workflow);setDraft(workflow.site);setChanges({});setMessage("");window.history.replaceState(null,"",`/jobs/${encodeURIComponent(nextId)}`);}catch(error){setMessage(error instanceof Error?error.message:"Could not load job.");}finally{setBusy(false);}}
 async function switchCustomer(customerId:string){if(!customerId||customerId===selectedCustomerId)return;if(Object.keys(changes).length&&!window.confirm("Discard unsaved changes and switch customer?"))return;setSelectedCustomerId(customerId);setSelectedJobId("");setChanges({});setDraft({});setData(current=>({...current,jobs:[]}));setMessage("Loading customer jobs...");setBusy(true);try{const response=await fetch(`/api/jobs?customerId=${encodeURIComponent(customerId)}`,{cache:"no-store"});const result=await response.json();if(!response.ok||!result.ok)throw Error(result.error??"Could not load customer jobs.");const options=(result.data??[]).map((row:{jobId:string;jobName:string})=>({id:Number(row.jobId),label:row.jobName}));setData(current=>({...current,jobs:options}));setMessage(options.length?"Select a job to load its details.":"This customer has no jobs.");}catch(error){setMessage(error instanceof Error?error.message:"Could not load customer jobs.");}finally{setBusy(false);}}
 async function openReport(name:string){const reportTypes:Record<string,string>={'Notice of Identification':'noi','Notice of Contract':'noc','Statement of Account':'statement','Satisfaction of Claim of Lien':'lien','Satisfaction of Notice of Contract':'satisfaction','Stop Payment Notice':'stop','Money Owed':'money'};if(reportTypes[name]){if(Object.keys(changes).length){setMessage('Save Job before opening a report.');return;}router.push('/jobs/'+job.jobId+'/reports?type='+reportTypes[name]);}else setTab(name);}
 function change(key:string,value:string|number|boolean|null){setDraft(old=>({...old,[key]:value}));setChanges(old=>({...old,[key]:value}));}
 function saveJob(){if('ProjectWCCID' in changes&&changes.ProjectWCCID!==data.site.ProjectWCCID){const note=window.prompt('Enter a note explaining the Job WC Code change.');if(note===null||!note.trim())return;void send({action:'save',fields:changes,wccChangeNote:note});return;}void send({action:'save',fields:changes});}
 async function send(body:Record<string,unknown>):Promise<boolean>{setBusy(true);setMessage('Saving...');try{const r=await fetch(`/api/jobs/${job.jobId}/site`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const result=await r.json();if(!r.ok)throw Error(result.error);const fresh=await fetch(`/api/jobs/${job.jobId}/site`);if(!fresh.ok)throw Error('Saved, but refresh failed');const updated=await fresh.json() as JobWorkflow;setData(updated);if(body.action==='save'||body.action==='repost'){setDraft(updated.site);setChanges({});}else{setDraft({...updated.site,...changes});}setMessage('Saved to database.');router.refresh();return true;}catch(error){setMessage(error instanceof Error?error.message:'Save failed');return false;}finally{setBusy(false);}}
 async function repostJob(){if(!window.confirm('Repost this job?'))return;if(Object.keys(changes).length){let wccChangeNote:string|undefined;if('ProjectWCCID' in changes&&changes.ProjectWCCID!==data.site.ProjectWCCID){const note=window.prompt('Enter a note explaining the Job WC Code change.');if(note===null||!note.trim())return;wccChangeNote=note;}const saved=await send({action:'save',fields:changes,...(wccChangeNote?{wccChangeNote}:{})});if(!saved)return;}await send({action:'repost'});}
 const select=(label:string,key:string,options:JobOption[])=> <Select label={label} value={draft[key]} options={options} onChange={value=>change(key,value?Number(value):null)}/>;
 const field=(label:string,key:string)=> <Field label={label} value={draft[key]} onChange={value=>change(key,key==='ProjectSort'?(value?Number(value):null):value)}/>;
 const gcLink=data.parties.find(row=>Number(row.id)===Number(data.site.ProjectGeneralContractorID));const contractor=data.contractors.find(row=>row.id===Number(gcLink?.masterId));
 const history=data.history.filter(row=>Object.values(row).join(' ').toLowerCase().includes(historySearch.toLowerCase()));
 const documentValue=String(data.documents[0]?.[tab]??'');const documentUrl=documentValue.includes('#')?documentValue.split('#')[1]:documentValue;
 const foreman=data.foremen.find(row=>row.id===Number(draft.SiteForemanID));
 return <section className={styles.screen}><header><label>Customers<select value={selectedCustomerId} onChange={e=>void switchCustomer(e.target.value)}>{data.customers.map(o=><option key={o.id} value={o.id}>{o.label}</option>)}</select></label><label>Jobs<select value={selectedJobId} disabled={busy} onChange={e=>void switchJob(e.target.value)}><option value=""></option>{data.jobs.map(o=><option key={o.id} value={o.id}>{o.label}</option>)}</select></label><div className={styles.credit}><Link href={`/customers/${selectedCustomerId}`}>Customer</Link><span>Contract Date</span><input readOnly value={selectedJobId?String(data.site.ContractDate??''):""}/></div><button disabled={busy||!selectedJobId||!Object.keys(changes).length} onClick={saveJob}>Save Job</button><Link href="/jobs">Back to Jobs</Link></header>{selectedJobId&&<><nav>{tabs.map(name=><button key={name} aria-pressed={tab===name} onClick={()=>setTab(name)}>{name==='Money Owed'?'Money Owed on This Job':name}</button>)}</nav><div className={styles.body}>{tab==='Site Data'?<><div className={styles.left}>{select('Job Status','ProjStatusID',data.statuses)}{field('Job Name','SiteName')}{field('Street','SiteStreet')}{select('City, State','SiteStateCityID',data.cities)}{field('Zip','SiteZip')}<button onClick={()=>setDialog({title:'Job History',rows:job.projectWeeks.map(w=>({id:w.weekId,'Week Ending':w.weekEnding,Year:w.assignYear,Week:w.assignWeek}))})}>History</button><div className={styles.space}/>{select('Subjob of','ParentProjectID',data.jobs)}{field('Sort','ProjectSort')}{select('Foreman Name','SiteForemanID',data.foremen)}<Field label="Cell #" value={foreman?.phone}/>{field('Start Time','ProjStartTime')}<Field label="Entry User/Date" value={`${job.entryUserName} ${job.entryTimestamp}`}/><h3>Placeholder Assignment History</h3><div className={styles.historyGrid}><table><thead><tr><th>Assignment Date</th><th>Count</th><th>Recruiter</th><th>History</th></tr></thead><tbody>{history.map(row=><tr key={String(row.id)}><td>{row['Assignment Date']}</td><td>{row.Count}</td><td>{row.Recruiter}</td><td><button onClick={()=>setDialog({title:'Assignment History',rows:[row]})}>Open</button></td></tr>)}</tbody></table></div><footer>Record: {history.length}<input aria-label="Search assignment history" value={historySearch} onChange={e=>setHistorySearch(e.target.value)}/></footer></div><div className={styles.notes}><h3>Special Job Instructions to show on directions</h3><Select label="Instructions Name" value={instruction} options={data.instructions} onChange={value=>{setInstruction(value);const selected=data.instructions.find(o=>o.id===Number(value));setInstructionName(selected?.label??'');change('ProjNote',selected?.text??'');}}/><div className={styles.instructionButtons}><button disabled={busy} onClick={()=>{if(!instructionName.trim()){setDialog({title:'Name this instruction template',rows:[]});return;}void send({action:'instruction-save',instructionId:Number(instruction)||null,name:instructionName,text:String(draft.ProjNote??'')});}}>Save Instructions</button><button disabled={!instruction||busy} onClick={()=>{if(window.confirm('Delete this shared instruction template? Job notes will remain.'))void send({action:'instruction-delete',instructionId:Number(instruction)});}}>Delete Instructions</button><button disabled={!instruction} onClick={()=>{setInstruction('');setInstructionName('');setDialog({title:'Name this instruction template',rows:[]});}}>Copy Instructions</button><button onClick={()=>{setInstruction('');setInstructionName('');change('ProjNote','');setDialog({title:'Name this instruction template',rows:[]});}}>New Instructions</button></div><textarea aria-label="Job instructions" value={String(draft.ProjNote??'')} onChange={e=>change('ProjNote',e.target.value)}/><h3>Office Note</h3><textarea aria-label="Office Note" value={String(draft.ProjOfficeNote??'')} onChange={e=>change('ProjOfficeNote',e.target.value)}/></div><div className={styles.parties}><div className={styles.flags}><button onClick={()=>setDialog({title:'Job History',rows:job.projectWeeks.map(w=>({id:w.weekId,'Week Ending':w.weekEnding,Year:w.assignYear,Week:w.assignWeek}))})}>Job History</button>{['DoNotShowOnInvoice','DoNotShowInTracking'].map(key=><label key={key}>{key==='DoNotShowOnInvoice'?'Do Not Show on Invoice':'Do Not Show in Tracking'}<input type="checkbox" checked={!!draft[key]} onChange={e=>change(key,e.target.checked)}/></label>)}</div><div className={styles.cards}><Party key={'gc'+String(data.site.ProjectGeneralContractorID)} title="General Contractor Information" kind="gc" options={data.contractors} cities={data.cities} current={contractor} onSave={send}/><Party key={'owner'+String(data.site.ProjectOwnerID)} title="Owner Information" kind="owner" options={data.owners} cities={data.cities} current={data.owners.find(o=>o.id===Number(data.site.ProjectOwnerID))} onSave={send}/><Party key={'bank'+String(data.site.ProjectBMFID)} title="Bank / MTG / Financier Information" kind="bank" options={data.banks} cities={data.cities} current={data.banks.find(o=>o.id===Number(data.site.ProjectBMFID))} onSave={send}/></div><h3>Verify General Contractor Info</h3><button onClick={()=>setDialog({title:'Contractor Verification History',rows:data.verifyHistory})}>History</button>{select('Where Info Came From or Override','GCVerifyMethodID',data.methods)}<Field label="Verify User" value={draft.GCVerifyUserName}/><Field label="Verify Date" value={draft.VerifyDate}/><label>Second Verify <input type="checkbox" checked={!!draft.GCSecondaryVerify} onChange={e=>change('GCSecondaryVerify',e.target.checked)}/></label><Field label="Second Verify User" value={draft.GCSecondaryVerifyUserName}/><Field label="Second Verify Date" value={draft.SecondVerifyDate}/><button onClick={()=>setDialog({title:'Master List of General Contractors',rows:data.contractors.map(o=>({id:o.id,Name:o.label,Street:o.street??'',Zip:o.zip??''}))})}>Master List of All General Contractors</button></div></>:tab==='Job Order'?<JobOrderTab data={data} draft={draft} change={change} onWccHistory={()=>setDialog({title:'Job WC Code History',rows:data.wccHistory})} onPostHistory={()=>setDialog({title:'Post History',rows:data.postHistory})} onRepost={()=>void repostJob()}/>:tab==='Notice of Identification'?<NoticeIdentificationTab jobId={job.jobId} data={data} onSave={send} onReport={()=>void openReport('Notice of Identification')}/>:tab==='Notice of Contract'?<NoticeContractTab job={job} data={data} onSave={send} onReport={()=>void openReport('Notice of Contract')}/>:tab==='Statement of Account'?<StatementAccountTab data={data} draft={draft} change={change} onReport={()=>void openReport('Statement of Account')}/>:tab==='Satisfaction of Claim of Lien'?<SatisfactionLienTab data={data} draft={draft} change={change} onReport={()=>void openReport('Satisfaction of Claim of Lien')}/>:tab==='Satisfaction of Notice of Contract'?<SatisfactionNoticeContractTab data={data} draft={draft} change={change} onReport={()=>void openReport('Satisfaction of Notice of Contract')}/>:tab==='Stop Payment Notice'?<StopPaymentNoticeTab data={data} draft={draft} change={change} onSave={send} onReport={()=>void openReport('Stop Payment Notice')}/>:tab==='Money Owed'?<MoneyOwedTab data={data} draft={draft} change={change} onSave={send} onReport={()=>void openReport('Money Owed')}/>:<div><h3>{tab}</h3>{['Notice of Identification','Notice of Contract','Statement of Account','Satisfaction of Claim of Lien','Satisfaction of Notice of Contract','Stop Payment Notice','Money Owed'].includes(tab)&&<button onClick={()=>void openReport(tab)}>Open report data / preview</button>}{legalTabs.includes(tab)?<>{(documentUrl.startsWith('https://')||documentUrl.startsWith('http://'))?<a href={documentUrl} target="_blank" rel="noreferrer">Open saved document</a>:<p>{documentValue?'Saved document path: '+documentUrl:'No saved document is linked to this job.'} Use Open report data / preview to view the original report layout.</p>}</>:tab==='Accident Reports'?<div className={styles.accidentTab}><div className={styles.accidentToolbar}><strong>Accident Reports for this Job:</strong><button onClick={()=>setAccidentModal(null)}>New Accident Report</button></div><div className={styles.accidentGrid}><table><colgroup><col className={styles.accidentDateCol}/><col/></colgroup><thead><tr><th>Date of Injury <span>?</span></th><th>Employee <span>?</span></th></tr></thead><tbody>{data.accidentReports.map(row=><tr key={String(row.id)} onDoubleClick={()=>setAccidentModal(String(row.id))} onClick={()=>setAccidentModal(String(row.id))} title="Open accident report"><td>{String(row['Date of Injury']??'')}</td><td>{String(row.Employee??'')}</td></tr>)}{Array.from({length:Math.max(0,15-data.accidentReports.length)},(_,index)=><tr className={styles.accidentBlankRow} key={`blank-${index}`}><td/><td/></tr>)}</tbody></table></div><footer className={styles.accidentFooter}>Record: {data.accidentReports.length?`1 of ${data.accidentReports.length}`:'0 of 0'}  ? No Filter  <span>Search</span></footer>{accidentModal!==undefined&&<AccidentReportModal key={accidentModal??'new'} id={accidentModal} initialProjectId={job.jobId} onClose={()=>setAccidentModal(undefined)} onSaved={()=>{setAccidentModal(undefined);void fetch(`/api/jobs/${job.jobId}/site`,{cache:'no-store'}).then(r=>r.json()).then((updated:JobWorkflow)=>setData(updated)).catch(()=>setMessage('The report was saved, but the job report list could not be refreshed.'));}}/>}</div>:tab==='Certified Payroll'?<CertifiedPayrollTab rows={data.certifiedPayroll} titles={data.certifiedPayrollTitles} cities={data.cities} draft={draft} change={change} onSave={body=>send(body)} onDelete={id=>send({action:'certified-payroll-delete',rowId:id})}/>:tab==='Contacts'?<ContactsTab contacts={data.contacts} onSave={body=>send(body)} onDelete={id=>send({action:'contact-delete',contactId:id})}/>:tab==='Directions'?<DirectionsTab jobId={Number(job.jobId)} salesmen={data.salesmen} job={{...job,startTime:draft.ProjStartTime,foreman:job.foremanName,notes:draft.ProjNote}}/>:<><Field label="Customer" value={job.customerName}/><Field label="Job" value={job.jobName}/><Field label="Contract Amount" value={job.contractAmount}/><Field label="Total Payments" value={job.contractTotalPayments}/><Field label="Balance Owed" value={job.contractBalanceOwed}/></>}{!legalTabs.includes(tab)&&<button onClick={()=>window.print()}>Print / Save PDF</button>}</div>}</div></>}<aside className={styles.sidebar}><label>Menu State<select value={menuState} onChange={e=>setMenuState(e.target.value)}>{Array.from(new Set(data.cities.map(o=>o.label.split(', ').at(-1)??''))).filter(Boolean).sort().map(state=><option key={state}>{state}</option>)}</select></label><h3>{menuState==='MA'?'Massachusetts':menuState}</h3>{[...tabs.slice(6),'Bond Claim'].map(name=><button key={name} onClick={()=>void openReport(name)}>{name==='Money Owed'?'Money Owed on This Job':name}</button>)}<label>Ignore data warnings when opening report screen<input type="checkbox" checked={ignoreWarnings} onChange={e=>setIgnoreWarnings(e.target.checked)}/></label></aside>{message&&<p role="status" className={styles.message} onClick={()=>setMessage('')}>{message}</p>}{dialog&&<div className={styles.overlay} role="dialog" aria-modal="true" aria-label={dialog.title}><div><h2>{dialog.title}</h2>{dialog.title==='Edit General Contractor'?<><Party title="General Contractor" kind="gc" options={data.contractors} cities={data.cities} current={data.contractors.find(o=>o.id===Number(dialog.rows[0]?.id))} onSave={body=>send({...body,action:'contractor-update'})}/><button onClick={()=>setDialog(null)}>Close</button></>:dialog.title==='Name this instruction template'?<><Field label="Name" value={instructionName} onChange={setInstructionName}/><button disabled={busy||!instructionName.trim()} onClick={()=>void send({action:'instruction-save',instructionId:Number(instruction)||null,name:instructionName,text:String(draft.ProjNote??'')}).then(()=>setDialog(null))}>Save Instructions</button><button onClick={()=>setDialog(null)}>Cancel</button></>:<><table><thead><tr>{Object.keys(dialog.rows[0]??{}).filter(key=>key!=='id').map(key=><th key={key}>{key}</th>)}</tr></thead><tbody>{dialog.rows.map((row,i)=><tr key={i}>{Object.entries(row).filter(([key])=>key!=='id').map(([key,value])=><td key={key}>{String(value??'')}{key==='Name'&&dialog.title==='Master List of General Contractors'&&<button onClick={()=>setDialog({title:'Edit General Contractor',rows:[row]})}>Edit</button>}</td>)}</tr>)}</tbody></table>{!dialog.rows.length&&<p>No history records.</p>}<button onClick={()=>setDialog(null)}>Close</button></>}</div></div>}</section>;
}
